function shrink(file,cb){var img=new Image();img.onload=function(){var m=1280,r=Math.min(1,m/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.round(img.width*r);c.height=Math.round(img.height*r);c.getContext('2d').drawImage(img,0,0,c.width,c.height);var u;try{u=c.toDataURL('image/jpeg',.8);}catch(e){u=img.src;}cb(u);};img.onerror=function(){cb(null);};img.src=URL.createObjectURL(file);}
