function km(a,b,c,d){var R=6371,p=Math.PI/180,x=(d-b)*p*Math.cos((a+c)/2*p),y=(c-a)*p;return Math.sqrt(x*x+y*y)*R;}
function nearSites(s,r){if(!DB.sites)return [];return DB.sites.filter(function(x){return Math.abs(x[0]-s.lat)<1.2&&km(s.lat,s.lon,x[0],x[1])<r;}).map(function(x){return {n:x[2]+(x[4]?' · '+x[4]:''),t:x[3],d:km(s.lat,s.lon,x[0],x[1]),lat:x[0],lon:x[1]};}).sort(function(a,b){return a.d-b.d;});}
