function bindAdv(){
  main.querySelectorAll('[data-fav]').forEach(function(b){b.addEventListener('click',function(){state.favs[b.dataset.fav]=!state.favs[b.dataset.fav];persist();rerender();});});
  main.querySelectorAll('[data-cmp]').forEach(function(b){b.addEventListener('click',function(){var i=state.cmp.indexOf(b.dataset.cmp);if(i>=0)state.cmp.splice(i,1);else{if(state.cmp.length>=4)state.cmp.shift();state.cmp.push(b.dataset.cmp);}persist();rerender();});});
  main.querySelectorAll('[data-zoom]').forEach(function(b){b.addEventListener('click',function(){var f=+b.dataset.zoom;if(!f)state.vb=[0,12,360,136];else zoom(f);rerender();});});
  main.querySelectorAll('[data-region]').forEach(function(b){b.addEventListener('click',function(){state.vb=(RVB[b.dataset.region]||RVB['전체']).slice();rerender();});});
  var ot=document.getElementById('osmToggle');if(ot)ot.addEventListener('change',function(){state.osm=ot.checked;rerender();});
  var bm=document.getElementById('bigmap');if(bm){var drag=null;
    bm.addEventListener('pointerdown',function(e){drag={x:e.clientX,y:e.clientY,vb:state.vb.slice(),moved:false};});
    bm.addEventListener('pointermove',function(e){if(!drag)return;var r=bm.getBoundingClientRect(),dx=(e.clientX-drag.x)/r.width*drag.vb[2],dy=(e.clientY-drag.y)/r.height*drag.vb[3];if(Math.abs(e.clientX-drag.x)+Math.abs(e.clientY-drag.y)>5)drag.moved=true;if(!drag.moved)return;state.vb=[Math.max(0,Math.min(360-drag.vb[2],drag.vb[0]-dx)),Math.max(0,Math.min(180-drag.vb[3],drag.vb[1]-dy)),drag.vb[2],drag.vb[3]];bm.setAttribute('viewBox',state.vb.join(' '));});
    var end=function(){if(drag&&drag.moved){drag=null;rerender();}drag=null;};bm.addEventListener('pointerup',end);bm.addEventListener('pointerleave',end);
    bm.addEventListener('wheel',function(e){e.preventDefault();zoom(e.deltaY<0?.8:1.25);rerender();},{passive:false});}
  var lq=document.getElementById('lq');if(lq){lq.addEventListener('input',function(){state.lq=lq.value;state.lpage=0;clearTimeout(lq._t);lq._t=setTimeout(function(){rerender();var n=document.getElementById('lq');if(n){n.focus();n.setSelectionRange(n.value.length,n.value.length);}},250);});}
  main.querySelectorAll('[data-lg]').forEach(function(b){b.addEventListener('click',function(){state.lg=b.dataset.lg;state.lpage=0;rerender();});});
  main.querySelectorAll('[data-lp]').forEach(function(b){b.addEventListener('click',function(){state.lpage+=+b.dataset.lp;rerender();});});
  main.querySelectorAll('[data-calc]').forEach(function(i){i.addEventListener('change',function(){var v=parseFloat(i.value);if(isFinite(v)&&v>0){state.calc[i.dataset.calc]=v;}rerender();});});
  main.querySelectorAll('[data-cost]').forEach(function(i){i.addEventListener('change',function(){var v=parseFloat(i.value);state.cost[i.dataset.cost]=isFinite(v)&&v>=0?v:0;rerender();});});
  main.querySelectorAll('[data-check]').forEach(function(i){i.addEventListener('change',function(){state.check[i.dataset.check]=i.checked;persist();rerender();});});
  main.querySelectorAll('[data-checkreset]').forEach(function(b){b.addEventListener('click',function(){state.check={};persist();rerender();});});
}
