function fstate(id){return state.forms[id]||(state.forms[id]={step:0,v:{},e:{}});}
function fopts(f){return typeof f.opts==='function'?f.opts():f.opts.map(function(o){return [o,o];});}
function fieldHtml(id,f,st){var v=st.v[f.k],e=st.e[f.k],fid='f_'+id+'_'+f.k,h='',full=' style="grid-column:1/-1"';
  if(f.type==='check')h='<label class="ck" for="'+fid+'"'+full+'><input id="'+fid+'" data-f="'+f.k+'" type="checkbox"'+(v?' checked':'')+'>'+f.l+'</label>';
  else if(f.type==='select')h='<label for="'+fid+'">'+f.l+(f.req?' *':'')+'<select id="'+fid+'" data-f="'+f.k+'"><option value="">선택</option>'+fopts(f).map(function(o){return '<option value="'+esc(o[0])+'"'+(v===o[0]?' selected':'')+'>'+esc(o[1])+'</option>';}).join('')+'</select></label>';
  else if(f.type==='multi')h='<fieldset'+full+'><legend>'+f.l+(f.req?' *':'')+'</legend><div class="chips">'+f.opts.map(function(o){var on=(v||[]).indexOf(o)>=0;return '<button class="chip" type="button" data-fm="'+f.k+'" data-o="'+o+'" aria-pressed="'+on+'">'+o+'</button>';}).join('')+'</div></fieldset>';
  else if(f.type==='textarea')h='<label for="'+fid+'"'+full+'>'+f.l+(f.req?' *':'')+'<textarea id="'+fid+'" data-f="'+f.k+'" rows="4" placeholder="'+esc(f.ph||'')+'">'+esc(v||'')+'</textarea></label>';
  else if(f.type==='file')h='<label for="'+fid+'">'+f.l+(f.req?' *':'')+'<input id="'+fid+'" data-ff="'+f.k+'" type="file">'+(v?'<span class="small">선택됨: '+esc(v)+'</span>':'')+'</label>';
  else h='<label for="'+fid+'">'+f.l+(f.req?' *':'')+'<input id="'+fid+'" data-f="'+f.k+'" type="'+f.type+'" value="'+esc(v==null?'':v)+'" placeholder="'+esc(f.ph||'')+'"'+(f.type==='password'?' autocomplete="new-password"':'')+'></label>';
  return e?h.replace(/<\/(label|fieldset)>$/,'<span class="err" role="alert">'+e+'</span></$1>'):h;}
function validate(id){var F=FORMS[id],st=fstate(id),ok=true;st.e={};F.steps[st.step].f.forEach(function(f){var v=st.v[f.k],empty=v==null||v===''||v===false||(Array.isArray(v)&&!v.length);
  if(f.req&&empty){st.e[f.k]=f.type==='check'?'동의가 필요해요':'입력해 주세요';ok=false;return;}
  if(empty)return;
  if(f.min&&String(v).length<f.min){st.e[f.k]=f.min+'자 이상 적어 주세요';ok=false;}
  else if(f.pat&&!f.pat.test(v)){st.e[f.k]=f.err;ok=false;}
  else if(f.same&&v!==st.v[f.same]){st.e[f.k]=f.err;ok=false;}
  else if(f.type==='number'&&(!isFinite(+v)||+v<0)){st.e[f.k]='0 이상의 숫자로 적어 주세요';ok=false;}});return ok;}
function formView(id){var F=FORMS[id],st=fstate(id),S=F.steps[st.step],last=st.step===F.steps.length-1;
  return '<div class="vh"><div><a class="small" href="#'+F.back+'">← 돌아가기</a><h1>'+F.title+'</h1><p>'+F.sub+'</p></div></div>'+
  '<ol class="steps">'+F.steps.map(function(s,i){return '<li'+(i===st.step?' aria-current="step"':'')+(i<st.step?' class="dn"':'')+'><b>'+(i+1)+'</b>'+s.t+'</li>';}).join('')+'</ol>'+
  '<form class="panel form" data-form="'+id+'" novalidate>'+S.f.map(function(f){return fieldHtml(id,f,st);}).join('')+
  '<div style="grid-column:1/-1;display:flex;gap:8px;justify-content:space-between;flex-wrap:wrap"><button class="btn btn-line" type="button" data-fprev="'+id+'"'+(st.step===0?' disabled style="visibility:hidden"':'')+'>이전</button><button class="btn btn-pri" type="submit">'+(last?'등록하기':'다음')+'</button></div>'+
  '<p class="small" style="grid-column:1/-1;margin:0">'+(BE.on?'작성 중인 내용은 이 기기에 임시 저장돼요. 비밀번호와 첨부 파일은 임시 저장하지 않아요.':'미리보기에서는 이 기기에만 저장되고 실제 계정 생성과 심사 접수는 되지 않아요.')+'</p></form>';}
Object.keys(FORMS).forEach(function(id){V[id]=function(){return formView(id);};});
