var side=document.getElementById('side');
side.innerHTML=MENU.map(function(m){return m.g?'<div class="grp">'+m.g+'</div>':'<a href="#'+m.id+'" data-nav="'+m.id+'">'+ic(m.i)+m.l+'</a>';}).join('');
var tabbar=document.getElementById('tabbar');
tabbar.innerHTML=TABS.map(function(id){var m=MENU.filter(function(x){return x.id===id;})[0];return '<a href="#'+id+'" data-nav="'+id+'">'+ic(m.i,22)+({home:'홈',map:'지도',feed:'피드',log:'로그',profile:'내 정보'})[id]+'</a>';}).join('');
