var gq=document.getElementById('gq'),gres=document.getElementById('gres');
var INDEX=SPOTS.map(function(s){return {t:s.name,s:EN[s.id]+' · '+s.country,h:'#spot-'+s.id,k:s.name+s.country+s.kind+EN[s.id]};})
 .concat(RESORTS.map(function(r){return {t:r.n,s:'리조트 · '+spot(r.spot).name,h:'#resorts',k:r.n+r.sub+spot(r.spot).name};}))
 .concat(PROS.map(function(p){return {t:p.n,s:p.sub,h:'#edu',k:p.sub+p.org};}))
 .concat(LIFE.map(function(l){return {t:l[0],s:LEN[LIFE.indexOf(l)]+' · '+l[1],h:'#life',k:l[0]+l[1]+l[2]+LEN[LIFE.indexOf(l)]};})).concat([{t:'장비 마켓',s:'중고 안전거래',h:'#gear',k:'장비 호흡기 bcd 컴퓨터 핀 마켓 중고'},{t:'정비 · 오버홀',s:'정비점 예약',h:'#gear',k:'정비 오버홀 수리'},{t:'자격증 단계',s:'PADI · AIDA',h:'#edu',k:'자격증 오픈워터 어드밴스드 aida padi'}]);
function doSearch(){var v=gq.value.trim().toLowerCase();if(!v){gres.classList.remove('open');return;}var r=INDEX.filter(function(x){return x.k.toLowerCase().indexOf(v)>=0||x.t.toLowerCase().indexOf(v)>=0;}).slice(0,7);gres.innerHTML=r.length?r.map(function(x){return '<a href="'+x.h+'">'+x.t+'<span>'+x.s+'</span></a>';}).join(''):'<p class="empty" style="padding:10px 12px;margin:0">찾는 결과가 없어요. 나라나 지역 이름으로 찾아보세요.</p>';gres.classList.add('open');}
gq.addEventListener('input',doSearch);
gres.addEventListener('click',function(){gres.classList.remove('open');gq.value='';});
document.addEventListener('click',function(e){if(!e.target.closest('.gsearch'))gres.classList.remove('open');});
gq.addEventListener('keydown',function(e){if(e.key==='Enter'){var f=gres.querySelector('a');if(f){location.hash=f.getAttribute('href');gres.classList.remove('open');gq.value='';}}if(e.key==='Escape')gres.classList.remove('open');});
// theme
document.getElementById('themeBtn').addEventListener('click',function(){var r=document.documentElement;var dark=r.dataset.theme?r.dataset.theme==='dark':matchMedia('(prefers-color-scheme: dark)').matches;r.dataset.theme=dark?'light':'dark';});
/*UP-START*/
var LABOUT=[
'세상에서 가장 큰 물고기로 다 자라면 12m를 넘기도 해요. 이빨 대신 아가미로 플랑크톤과 작은 물고기를 걸러 먹어서 사람에게는 위협이 되지 않아요.',
'날개처럼 펼친 가슴지느러미 폭이 3~5m쯤이에요. 산호초 근처 청소 스테이션에 들러 작은 물고기에게 몸을 맡기고, 입을 벌린 채 플랑크톤을 걸러 먹어요.',
'가오리 가운데 가장 커서 폭이 7m에 이르기도 해요. 먼바다를 떠돌며 살고, 등에 T자 모양 흰 무늬와 입 안쪽이 검은 것으로 리프 만타와 구분해요.',
'몸길이만큼 긴 꼬리 윗부분이 특징이에요. 꼬리를 채찍처럼 휘둘러 정어리 떼를 기절시켜 잡아먹고, 이른 아침 청소 스테이션에서 자주 보여요.',
'망치처럼 옆으로 넓은 머리 양끝에 눈이 달려 있어요. 넓은 머리로 먹이의 전기 신호를 잘 잡아내고, 큰 무리를 지어 다니는 종도 있어요.',
'인도·태평양 산호초에서 가장 흔한 상어 가운데 하나예요. 꼬리지느러미 뒤 가장자리가 검고, 위협을 느끼면 등을 구부리고 지느러미를 내리는 경고 자세를 해요.',
'지느러미 끝이 검게 물들어 있고 얕은 모래 바닥이나 산호초 가장자리에서 자주 보여요. 몸길이 1.5m 안팎으로 겁이 많은 편이에요.',
'등지느러미와 꼬리 끝이 하얀 작은 상어예요. 낮에는 바위 밑이나 굴에서 쉬고 밤에 먹이를 찾아 나와요.',
'몸에 호랑이 같은 줄무늬가 있고 커지면 4~5m까지 자라요. 거의 무엇이든 먹는 대형 포식자라 가이드 브리핑을 꼭 따라야 해요.',
'짧고 뭉툭한 주둥이에 몸이 굵은 상어로 민물이 섞인 강 하구에도 들어가요. 탁한 물에서 만날 수 있어 주의가 필요해요.',
'긴 가슴지느러미 끝이 둥글고 하얀 먼바다 상어예요. 호기심이 많아 다이버에게 다가오기도 하니 수면 근처에서 무리 지어 있는 게 안전해요.',
'날카로운 이빨이 입 밖으로 보여 무섭게 생겼지만 움직임이 느리고 온순한 편이에요. 수면에서 공기를 삼켜 부력을 맞추는 독특한 습성이 있어요.',
'어릴 때는 얼룩말 같은 줄무늬, 커서는 표범 같은 점무늬로 바뀌어요. 낮에는 모래 바닥에 가만히 누워 쉬는 모습을 자주 볼 수 있어요.',
'입가에 수염 같은 돌기가 있고 바닥에 붙어 쉬는 걸 좋아해요. 순하지만 건드리면 물 수 있어요.',
'납작한 몸과 술 장식 같은 피부로 바닥에 완벽하게 숨어요. 다가오는 물고기를 기다렸다 한입에 삼키는 매복형 상어예요.',
'세계에서 가장 무거운 경골어류로 1톤을 넘기도 해요. 깊은 바다에 살다가 체온을 올리거나 기생충을 떼려고 얕은 곳으로 올라와요.',
'모래 바닥에 몸을 묻고 눈만 내놓고 있어요. 꼬리에 독가시가 있으니 바닥에 손을 짚거나 밟지 않게 조심해야 해요.',
'길이 15m 안팎으로 긴 가슴지느러미가 특징이에요. 번식기에 따뜻한 바다로 내려와 수컷이 긴 노래를 불러요.',
'혹등고래보다 훨씬 작은 7~8m의 밍크고래 아종이에요. 호주 그레이트배리어리프 북쪽에서 6~7월에 다이버 곁으로 다가오곤 해요.',
'연안 가까이 사는 돌고래로 몸길이 2.5m 안팎이에요. 무리를 지어 다니고 사람에게 호기심을 보이기도 해요.',
'물 위로 뛰어올라 몸을 여러 번 비틀어 도는 행동으로 이름이 붙었어요. 낮에는 만에서 쉬고 밤에 먼바다로 사냥을 나가요.',
'바다풀을 뜯어 먹는 초식 포유류로 꼬리가 돌고래처럼 생겼어요. 해초밭이 사라지면서 수가 줄어 보호 대상이에요.',
'귀가 겉으로 보이고 앞지느러미로 몸을 세울 수 있어요. 장난기가 많아 다이버 주변을 맴돌며 놀기도 해요.',
'어른이 되면 바다풀과 해조류를 주로 먹어요. 지방이 초록빛을 띠어 이름이 붙었고 등딱지는 1m 안팎이에요.',
'매의 부리처럼 뾰족한 입으로 해면을 뜯어 먹어요. 등딱지 무늬가 아름다워 남획됐고 지금은 심각한 멸종 위기종이에요.',
'가장 큰 바다거북으로 딱딱한 등딱지 대신 가죽 같은 피부가 있어요. 해파리를 주로 먹고 아주 깊이 잠수해요.',
'수십만 마리가 한 덩어리로 움직이며 모양을 계속 바꿔요. 포식자가 나타나면 공 모양으로 뭉치는 베이트볼을 만들어요.',
'은빛 몸이 길고 아래턱이 튀어나와 있어요. 낮에는 소용돌이 모양으로 천천히 돌며 무리 지어 떠 있어요.',
'눈이 큰 전갱이류로 수백 마리가 원을 그리며 돌아요. 조류가 있는 곳에서 자주 만나요.',
'이마가 혹처럼 튀어나온 가장 큰 앵무고기예요. 이빨로 산호를 갉아 먹고 소화한 뒤 하얀 모래로 내보내요.',
'두툼한 입술과 이마의 혹이 특징인 큰 놀래기로 2m 가까이 자라요. 사람을 무서워하지 않고, 개체 수가 줄어 보호종이에요.',
'전갱이류 가운데 가장 커서 1.5m를 넘기도 해요. 빠르게 돌진해 사냥하는 모습을 볼 수 있어요.',
'감자 같은 얼룩무늬가 있는 큰 그루퍼예요. 호기심이 많아 다이버에게 가까이 다가와요.',
'300kg을 넘기도 하는 거대한 그루퍼예요. 난파선이나 굴 주변에 머물며 큰 소리를 내기도 해요.',
'노란 줄무늬 스내퍼가 수백 마리 모여 한자리에 떠 있어요. 사진으로 담기 좋은 장면이에요.',
'개처럼 날카로운 이빨이 있는 다랑어로 조류 센 절벽에서 사냥해요. 빠르게 지나가니 눈을 크게 뜨고 있어야 해요.',
'한국과 일본 바다에서 겨울에 큰 무리로 나타나는 전갱이류예요. 빠르게 지나가는 은빛 무리가 장관이에요.',
'말미잘과 함께 살며 서로 도와요. 말미잘 독침에 쏘이지 않는 점액이 몸을 감싸고 있고, 무리에서 가장 큰 개체가 암컷이 돼요.',
'파랑·주황 무늬가 화려한 작은 물고기로 해 질 녘 산호 사이에서 짝짓기를 해요. 빛을 싫어하니 조명은 약하게 비춰 주세요.',
'모래 바닥에 몸 대부분을 묻고 머리만 내밀어 플랑크톤을 먹어요. 다가가면 쏙 숨어 버리니 멀리서 천천히 봐야 해요.',
'두툼한 입술과 점무늬가 특징으로 낮에는 산호 아래 무리 지어 쉬어요. 어릴 때와 커서의 무늬가 크게 달라요.',
'몸이 납작하고 지느러미가 위아래로 길어요. 다이버를 따라오며 주변을 맴도는 경우가 많아요.',
'몸이 납작하고 색이 화려한 산호초 물고기예요. 해면이나 조류를 먹고 텃세가 있는 편이에요.',
'작고 동그란 몸에 눈을 가리는 줄무늬가 있어요. 짝을 지어 다니는 경우가 많고 산호 폴립을 먹어요.',
'뱀처럼 긴 몸으로 바위 틈에 살아요. 입을 벌렸다 닫는 건 숨을 쉬는 동작이에요. 손을 틈 안에 넣지 마세요.',
'리본처럼 가는 몸에 콧구멍이 꽃잎처럼 펼쳐져 있어요. 어릴 때 검정, 수컷일 때 파랑, 암컷일 때 노랑으로 색이 바뀌어요.',
'은빛 비늘이 큰 대형 물고기로 1~2m까지 자라요. 동굴이나 그늘진 곳에 무리 지어 머물러요.',
'껍데기 없는 바다달팽이로 색과 모양이 수천 가지예요. 먹은 먹이의 독이나 색을 몸에 저장하기도 해요.',
'2cm 남짓한 아주 작은 해마로 부채산호와 색과 돌기가 똑같아요. 가이드가 찾아줘야 보일 만큼 위장이 뛰어나요.',
'꼬리로 해초나 산호를 감고 머물러요. 수컷 배 주머니에서 새끼가 태어나요.',
'몸이 해면처럼 생긴 매복형 물고기예요. 머리 위 낚싯대 같은 돌기로 먹이를 유인해 순식간에 삼켜요.',
'온몸이 털 같은 돌기로 덮여 해조류처럼 보이는 씬벵이예요. 인도네시아 렘베에서 특히 자주 보여요.',
'해마와 가까운 종으로 해초나 바다나리에 몸을 기대 떠 있어요. 몸 색과 모양이 주변과 똑같아 찾기 어려워요.',
'화려한 술 장식이 있는 쏨뱅이류로 아주 드물게 보여요. 등지느러미에 독가시가 있어요.',
'불가사리를 먹는 작은 새우로 하얀 바탕에 분홍 점무늬가 있어요. 보통 한 쌍이 함께 살아요.',
'망치 같은 앞다리로 아주 빠르게 쳐서 조개를 깨요. 사람이 볼 수 없는 색까지 구분하는 눈을 가졌어요.',
'갯민숭달팽이나 해삼 위에 붙어 사는 작은 새우예요. 숙주를 타고 이동하며 그 위에서 먹이를 얻어요.',
'몸 색과 자세를 바꿔 넙치, 바다뱀, 쏠배감펭 같은 다른 생물을 흉내 내요. 모래 바닥에서 주로 보여요.',
'몸 색이 보라·노랑·빨강으로 물결치듯 바뀌는 작은 갑오징어예요. 헤엄보다 바닥을 걷듯 움직여요.',
'코코넛 껍데기나 조개껍데기를 들고 다니다 위험하면 그 안에 숨어요. 도구를 쓰는 무척추동물로 알려져 있어요.',
'갑오징어 가운데 가장 커서 50cm에 이르기도 해요. 번식기에 남호주 바다에 수만 마리가 모여요.',
'몸 색과 피부 질감을 순식간에 바꾸는 위장의 달인이에요. 굴 앞에 껍데기를 쌓아 두는 습성이 있어요.',
'뼈대 없이 부드러운 몸을 가진 산호로 물이 흐를 때 폴립을 펼쳐 먹이를 잡아요. 색이 화려해 사진에 잘 담겨요.',
'부채처럼 넓게 펼쳐진 산호로 조류 방향에 맞서 자라요. 크게는 몇 미터까지 펼쳐져요.',
'석회질 골격을 쌓아 산호초를 만드는 산호예요. 몸 안의 조류와 함께 살아서 수온이 오르면 하얗게 변하는 백화가 생겨요.',
'1m 넘게 자라는 조개로 외투막 색이 형광처럼 화려해요. 몸속 조류가 만든 양분을 받아 살아요.',
'불가사리와 친척인 극피동물로 깃털 같은 팔을 펼쳐 플랑크톤을 걸러요. 팔을 흔들며 헤엄치기도 해요.',
'제주 바다에서 가장 흔하게 보이는 작은 물고기예요. 큰 무리로 다니며 제주에서는 물회로도 먹어요.',
'하얗고 솜털 같은 촉수가 꽃처럼 피는 말미잘이에요. 동해와 남해 차가운 바다 바위에 무리 지어 붙어 있어요.',
'분홍·보라색으로 나무처럼 가지를 뻗는 연산호예요. 제주 문섬과 섶섬 바다를 대표하는 풍경이에요.',
'한국 바위 해안에 흔한 물고기로 겨울에 산란해요. 수컷이 알을 지키는 모습을 볼 수 있어요.',
'이마가 크게 튀어나온 대형 놀래기예요. 동해와 남해 바위 지대에서 다이버에게 다가오기도 해요.',
'어릴 때 몸에 굵은 검은 줄이 있어요. 단단한 이빨로 성게와 조개를 깨 먹어요.',
'바위 틈과 해조류 숲에 사는 물고기로 큰 눈이 특징이에요. 한국 바다 다이빙에서 자주 만나요.',
'겉은 하얗거나 갈색이지만 골격이 검어서 이름이 붙었어요. 제주 바다에서 자라는 보호종이에요.',
'몸길이 10~20cm의 작은 문어지만 맹독이 있어요. 위협을 느끼면 파란 고리 무늬가 선명하게 빛나요. 절대 만지지 마세요.',
'바위나 산호와 구분이 안 될 만큼 위장을 잘해요. 등지느러미 독가시에 찔리면 극심한 통증이 생기니 바닥을 짚지 마세요.',
'부채처럼 펼친 지느러미가 화려한 쏨뱅이류예요. 지느러미 가시에 독이 있고 대서양에서는 외래종으로 문제가 되고 있어요.',
'원뿔 모양 껍데기를 가진 고둥으로 작살 같은 독침을 쏴요. 예쁜 껍데기라도 집어 들지 마세요.',
'숨을 쉬러 수면에 올라오는 파충류예요. 독이 강하지만 대체로 온순하니 건드리지 않으면 괜찮아요.',
'산란기에 둥지 주변을 지키며 다이버를 공격하기도 해요. 둥지는 위쪽으로 원뿔 모양이라 위로 올라가지 말고 옆으로 피하세요.',
'산호처럼 생겼지만 해파리와 가까운 생물이에요. 닿으면 화끈거리며 쏘이니 장갑 없이 만지지 마세요.',
'정육면체 모양 갓에 긴 촉수가 달린 해파리로 독이 매우 강해요. 출몰 시기에는 스틴거 슈트를 입어요.',
'뾰족한 가시가 몸을 덮고 있어요. 밟거나 짚으면 가시가 박혀 부러지니 입수·출수할 때 발밑을 조심하세요.',
'꼬리에 톱니 같은 독가시가 있어요. 모래 바닥에 숨어 있으니 얕은 곳에서는 발을 끌듯이 걸으세요.'
];

