  if(f.auto)h=h.replace('autocomplete="new-password"','').replace('<input ','<input autocomplete="'+f.auto+'" ');
  if(f.type==='email')h=h.replace('<input ','<input inputmode="email" autocapitalize="off" ');
  if(f.type==='number'||f.mode==='numeric')h=h.replace('<input ','<input inputmode="numeric" ');
  if(f.phone)h=h.replace('<input ','<input inputmode="tel" ');
