var CHO='ㄱㄲㄴㄷㄸㄹㅁㅂㅃㅅㅆㅇㅈㅉㅊㅋㅌㅍㅎ';
function cho(s){return String(s||'').replace(/[가-힣]/g,function(c){return CHO[Math.floor((c.charCodeAt(0)-44032)/588)];});}
function kmatch(text,q){q=String(q||'').trim().toLowerCase();if(!q)return true;text=String(text||'').toLowerCase();if(text.indexOf(q)>=0)return true;if(/^[ㄱ-ㅎ]+$/.test(q.replace(/\s/g,'')))return cho(text).replace(/\s/g,'').indexOf(q.replace(/\s/g,''))>=0;return false;}

