function threads(){var me=BE.user.id,T={};(state.inbox||[]).forEach(function(m){var o=m.sender===me?m.recipient:m.sender,k=o+'|'+(m.item_id||'');(T[k]||(T[k]={other:o,item:m.item_id,msgs:[],nick:null})).msgs.push(m);if(m.sender!==me)T[k].nick=m.sender_nick;});return Object.keys(T).map(function(k){var t=T[k];t.key=k;t.last=t.msgs[t.msgs.length-1];t.unread=t.msgs.filter(function(m){return m.recipient===me&&!m.read_at;}).length;return t;}).sort(function(a,b){return a.last.created_at<b.last.created_at?1:-1;});}
