  var mo=new Date().getMonth()+1,names={};inSeason().forEach(function(s){s.life.forEach(function(l){names[l]=(names[l]||0)+1;});});var top=Object.keys(names).sort(function(a,b){return names[b]-names[a];}).slice(0,10);
  if(top.length)h=h.replace('<div class="panel"><h2>'+state.lcat,'<div class="panel"><h2>'+mo+'월에 만나기 좋은 생물</h2><div class="chips">'+top.map(function(n){return '<button class="chip" type="button" data-lifepick="'+esc(n)+'">'+esc(n)+'</button>';}).join('')+'</div><p class="small" style="margin:8px 0 0">지금이 시즌인 포인트에서 자주 만나는 생물이에요.</p></div><div class="panel"><h2>'+state.lcat);
  h=h.replace(/<button class="chip" type="button" data-seen="(\d+)"/g,function(m,i){return '<span style="display:flex;gap:6px;flex-wrap:wrap"><button class="chip" type="button" data-lshare="'+i+'">공유</button><button class="chip" type="button" data-report="species" data-rid="'+(+i+1)+'">틀린 정보 알리기</button></span>'+m;});
